// AIG - Ethiopian (Ge'ez) date display - READ-ONLY reference only.
// The operative/posting date stays Gregorian. This display field stores
// nothing (HTML fieldtype) and does not affect validation, fiscal periods,
// or workflows. Algorithm verified against calendar anchors before deploy.
(function () {
	const MONTHS = ["Meskerem","Tikimt","Hidar","Tahsas","Tir","Yekatit","Megabit",
		"Miyazya","Ginbot","Sene","Hamle","Nehase","Pagume"];
	const EPOCH = 1724223; // JDN of 1 Meskerem 1 EC (Amete Mihret; leap years = 3 mod 4)

	function g2j(y, m, d) {
		return Math.floor((1461 * (y + 4800 + Math.floor((m - 14) / 12))) / 4)
			+ Math.floor((367 * (m - 2 - 12 * Math.floor((m - 14) / 12))) / 12)
			- Math.floor((3 * Math.floor((y + 4900 + Math.floor((m - 14) / 12)) / 100)) / 4)
			+ d - 32075;
	}
	function j2e(jdn) {
		const days = jdn - EPOCH;
		if (days < 0) return null;
		const cycle = Math.floor(days / 1461);
		const idx = days % 1461;
		let year, doy;
		if (idx < 365) { year = 1; doy = idx; }
		else if (idx < 730) { year = 2; doy = idx - 365; }
		else if (idx < 1096) { year = 3; doy = idx - 730; }
		else { year = 4; doy = idx - 1096; }
		year = cycle * 4 + year;
		let month, day;
		if (doy < 360) { month = Math.floor(doy / 30) + 1; day = (doy % 30) + 1; }
		else { month = 13; day = doy - 359; }
		return { year: year, month: month, day: day, monthName: MONTHS[month - 1] };
	}
	function toEth(greg) {
		if (!greg) return null;
		const parts = greg.split("-");
		if (parts.length !== 3) return null;
		const y = +parts[0], m = +parts[1], d = +parts[2];
		if (!y || !m || !d) return null;
		return j2e(g2j(y, m, d));
	}
	function update(frm) {
		const f = frm.fields_dict.aig_eth_date_display;
		if (!f || !f.$wrapper) return;
		const e = toEth(frm.doc.transaction_date);
		const txt = e ? (e.day + " " + e.monthName + " " + e.year + " EC") : "\u2014";
		f.$wrapper.html(
			'<div style="padding:2px 0;font-weight:500;color:#3d4657;">'
			+ '<span title="Ethiopian (Ge\u2019ez) calendar equivalent - display only">'
			+ txt + '</span></div>'
		);
	}
	frappe.ui.form.on("Purchase Order", {
		refresh: update,
		transaction_date: update
	});
})();

