(function () {
	var FLAG = "__aig_cc_scrubbed";
	function target_cc(frm) {
		return frm.doc.aig_cost_center || null;
	}
	function apply(frm, v) {
		if (frm.doc.cost_center !== v) {
			frappe.model.set_value(frm.doc.doctype, frm.doc.name, "cost_center", v);
		}
	}
	function scrub(frm, force) {
		var target = target_cc(frm);
		// header: on a NEW doc, ERPNext injected the Company default CC. Until
		// the user picks the enterprise CC, clear it so permission checks pass.
		if (frm.doc.__islocal || force) {
			apply(frm, target || null);
		}
		(frm.doc.items || []).forEach(function (row) {
			var want = target || null;
			if (row.cost_center && row.cost_center !== want) {
				frappe.model.set_value(row.doctype, row.name, "cost_center", want);
			}
		});
		frm.__aig_cc_scrubbed = true;
	}
	frappe.ui.form.on("Stock Entry", {
		refresh: function (frm) {
			if (!frm[FLAG]) { scrub(frm, false); frm[FLAG] = true; }
		},
		aig_cost_center: function (frm) { scrub(frm, true); },
		stock_entry_type: function (frm) { scrub(frm, true); }
	});
	frappe.ui.form.on("Stock Entry Item", {
		item_code: function (frm) { setTimeout(function () { scrub(frm, false); }, 900); },
		s_warehouse: function (frm) { setTimeout(function () { scrub(frm, false); }, 900); },
		t_warehouse: function (frm) { setTimeout(function () { scrub(frm, false); }, 900); }
	});
})();

