(function () {
	function is_end_user_only() {
		var roles = frappe.user_roles || [];
		return roles.indexOf("AIG End User") >= 0
			&& roles.indexOf("AIG Procurement Officer") < 0
			&& roles.indexOf("AIG Inventory Administrator") < 0
			&& roles.indexOf("AIG Main Store Administrator") < 0;
	}
	frappe.ui.form.on("Material Request", {
		onload: function (frm) {
			if (!is_end_user_only()) { return; }
			frm.set_df_property("material_request_type", "read_only", 1);
			if (frm.is_new() && frm.doc.material_request_type !== "Material Issue") {
				frm.set_value("material_request_type", "Material Issue");
			}
		}
	});
})();

// AIG - SE CC Intercept: ERPNext's async item-detail fill stamps the
// Company default Cost Center (Head Office - AIG) onto rows. For
// enterprise-scoped users that CC fails the doc-level CREATE check at Save
// ('You need the create permission on Stock Entry'). This row-level handler
// fires the instant the fill writes cost_center (model event, no timeouts)
// and reverts the poison to the enterprise CC (header) or empty.
(function () {
	var POISON = "Head Office - AIG";
	function target(frm) {
		return frm.doc.aig_cost_center || frm.doc.aig_dest_cost_center || null;
	}
	frappe.ui.form.on("Stock Entry Item", {
		cost_center: function (frm, cdt, cdn) {
			var row = locals[cdt] && locals[cdt][cdn];
			if (!row || !row.cost_center) return;
			var want = target(frm);
			if (row.cost_center === POISON && row.cost_center !== want) {
				frappe.model.set_value(cdt, cdn, "cost_center", want || null);
			}
		}
	});
	frappe.ui.form.on("Stock Entry", {
		refresh: function (frm) {
			// a new doc must never carry the Company default as its dimension
			if (frm.doc.__islocal && frm.doc.aig_cost_center === POISON) {
				frm.set_value("aig_cost_center", null);
			}
		},
		aig_cost_center: function (frm) {
			var want = target(frm);
			(frm.doc.items || []).forEach(function (row) {
				if (row.cost_center === POISON && row.cost_center !== want) {
					frappe.model.set_value(row.doctype, row.name, "cost_center", want || null);
				}
			});
		}
	});
})();

// AIG - MR CC Intercept: ERPNext/the CC-sync script can stamp the root CC
// or Head Office onto a new Material Request. Enterprise users cannot read
// such documents at doc level, which silently kills their workflow buttons.
// This model-event guard instantly reverts those values on a new MR.
(function () {
	var POISON = ["Adama Investment Group - AIG", "Head Office - AIG"];
	function is_poison(v) {
		return v && POISON.indexOf(v) !== -1;
	}
	frappe.ui.form.on("Material Request", {
		aig_cost_center: function (frm) {
			if (frm.doc.__islocal && is_poison(frm.doc.aig_cost_center)) {
				frm.set_value("aig_cost_center", null);
			}
		}
	});
	frappe.ui.form.on("Material Request Item", {
		cost_center: function (frm, cdt, cdn) {
			var row = locals[cdt] && locals[cdt][cdn];
			if (frm.doc.__islocal && row && is_poison(row.cost_center)) {
				frappe.model.set_value(cdt, cdn, "cost_center", null);
			}
		}
	});
})();

// AIG - Item Code Auto Hint: demo users never type Item Codes -- the server
// generates AIG-<group>-<sequence> on save. Make the field read-only with a
// hint (Administrator keeps manual override).
(function () {
	frappe.ui.form.on("Item", {
		refresh: function (frm) {
			if (frappe.session.user === "Administrator") return;
			var df = frm.fields_dict.item_code;
			if (df) {
				df.df.read_only = 1;
				df.df.description = "Leave empty -- AIG generates the code from the Item Group (AIG-<group>-<sequence>).";
				frm.refresh_field("item_code");
			}
		}
	});
})();
